import {useEffect,useState} from 'react';
import {createRoot} from 'react-dom/client';
import * as I from 'lucide-react';
import {Bar,Doughnut} from 'react-chartjs-2';
import {Chart as ChartJS,ArcElement,BarElement,CategoryScale,Legend,LinearScale,Tooltip} from 'chart.js';
import './styles.css';
import './analytics.css';
import './mobile.css';
import {FinalApp} from './final-app.jsx';

ChartJS.register(ArcElement,BarElement,CategoryScale,Legend,LinearScale,Tooltip);

const KEY='careflow_offline_complete_v2';
const API=import.meta.env.VITE_API_URL||'http://localhost:8012/api';
const id=()=>crypto.randomUUID(); const iso=()=>new Date().toISOString(); const show=d=>new Date(d).toLocaleString([],{dateStyle:'medium',timeStyle:'short'});
const dateKey=d=>{const x=new Date(d);return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`};
const reminderTimeKey=value=>/^\d{2}:\d{2}$/.test(String(value||''))?value:new Date(`1970-01-01 ${value}`).toTimeString().slice(0,5);
const uid=id;
const seed=()=>({users:[{id:'p1',role:'patient',name:'Aanya Sharma',email:'patient@careflow.com',pass:'patient123',blood:'O+',allergies:'Penicillin'},{id:'d1',role:'doctor',name:'Dr. Meera Iyer',email:'doctor@careflow.com',pass:'doctor123',specialty:'General Medicine',fee:700,approved:true},{id:'d2',role:'doctor',name:'Dr. Rohan Shah',email:'rohan@careflow.com',pass:'doctor123',specialty:'Cardiology',fee:900,approved:true},{id:'d3',role:'doctor',name:'Dr. Kavya Patel',email:'kavya@careflow.com',pass:'doctor123',specialty:'Dermatology',fee:750,approved:true},{id:'d4',role:'doctor',name:'Dr. Arjun Rao',email:'arjun@careflow.com',pass:'doctor123',specialty:'Orthopedics',fee:800,approved:false},{id:'a1',role:'admin',name:'System Admin',email:'admin@careflow.com',pass:'admin123'}],slots:[{id:'s1',doctor:'d1',at:'2026-08-26T10:30:00',booked:true},{id:'s2',doctor:'d1',at:'2026-08-26T11:15:00',booked:false},{id:'s3',doctor:'d1',at:'2026-08-26T14:00:00',booked:false},{id:'s4',doctor:'d2',at:'2026-08-26T12:00:00',booked:false},{id:'s5',doctor:'d2',at:'2026-08-26T15:30:00',booked:false},{id:'s6',doctor:'d3',at:'2026-08-26T16:30:00',booked:false}],appointments:[{id:'a1',patient:'p1',doctor:'d1',slot:'s1',status:'confirmed',priority:false,wait:18,created:'2026-08-25T08:00:00'}],records:[{id:'r1',patient:'p1',title:'Welcome consultation',type:'Encounter',detail:'Initial health profile reviewed. Hydration and rest advised.',created:'2026-08-20T09:30:00'}],prescriptions:[{id:'rx1',patient:'p1',medicine:'Vitamin D3',dose:'1 tablet',time:'08:00 AM',notes:'Take after breakfast.',created:'2026-08-20T09:30:00'}],reminders:[{id:'m1',patient:'p1',medicine:'Vitamin D3',dose:'1 tablet',time:'08:00 AM',active:true},{id:'m2',patient:'p1',medicine:'Amoxicillin 500 mg',dose:'1 capsule',time:'09:00 AM',active:true}],symptoms:[],departments:['General Medicine','Cardiology','Dermatology','Pediatrics','Orthopedics','Neurology'],disputes:[{id:'x1',title:'Cancellation request — Aanya Sharma',status:'Open'}]});
function futureSlots(state){const now=new Date();(state.slots||[]).forEach((slot,index)=>{if(new Date(slot.at)<now){const original=new Date(slot.at),next=new Date(now);next.setDate(now.getDate()+1+Math.floor(index/3));next.setHours(original.getHours(),original.getMinutes(),0,0);slot.at=next.toISOString()}});return state}
function store(){try{return futureSlots(JSON.parse(localStorage.getItem(KEY))||seed())}catch{return futureSlots(seed())}}
function hydrate(remote){const fallback=seed();if(!remote)return store();const passwords=new Map(fallback.users.map(x=>[x.email,x.pass]));return futureSlots({...fallback,...remote,symptoms:remote.symptoms||[],users:(remote.users||fallback.users).map(x=>({...x,pass:passwords.get(x.email)||x.pass||''}))})}
function persist(data,setSync){const safe=structuredClone(data);safe.users=safe.users.map(({pass,...user})=>user);fetch(`${API}/demo-state`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({state:safe})}).then(r=>{if(!r.ok)throw new Error();setSync('MongoDB synchronized')}).catch(()=>setSync('Offline backup active'))}
function useData(){const [data,setData]=useState(store),[sync,setSync]=useState('Connecting to MongoDB…');const load=()=>fetch(`${API}/demo-state`).then(r=>r.json()).then(({state})=>{if(state){const merged=hydrate(state);localStorage.setItem(KEY,JSON.stringify(merged));setData(merged)}else persist(store(),setSync);setSync('MongoDB synchronized')}).catch(()=>setSync('Offline backup active'));useEffect(()=>{load();const refresh=()=>load();window.addEventListener('focus',refresh);const timer=window.setInterval(refresh,10000);return()=>{window.removeEventListener('focus',refresh);window.clearInterval(timer)}},[]);const edit=f=>setData(x=>{const y=structuredClone(x);f(y);localStorage.setItem(KEY,JSON.stringify(y));persist(y,setSync);return y});const reset=()=>{const x=seed();localStorage.setItem(KEY,JSON.stringify(x));setData(x);persist(x,setSync)};return[data,edit,reset,sync]}
const findUser=(d,x)=>d.users.find(v=>v.id===x);const findSlot=(d,x)=>d.slots.find(v=>v.id===x);const initials=x=>x.replace('Dr. ','').split(' ').map(v=>v[0]).join('').slice(0,2);
const NAV={patient:[['home','Home',I.Home],['book','Book visit',I.CalendarPlus],['appointments','Appointments',I.CalendarDays],['records','Health records',I.FolderHeart],['symptoms','AI navigator',I.Sparkles],['reminders','Reminders',I.BellRing],['profile','Profile',I.User]],doctor:[['home','Dashboard',I.LayoutDashboard],['queue','Live queue',I.Users],['schedule','Availability',I.CalendarDays],['patients','Patients',I.ClipboardList],['emergencies','Emergency cases',I.AlertTriangle],['profile','Profile',I.User]],admin:[['home','Dashboard',I.LayoutDashboard],['approvals','Doctor approvals',I.BadgeCheck],['departments','Departments',I.Building2],['analytics','Analytics & reports',I.BarChart3],['disputes','Disputes',I.MessageSquareWarning],['profile','Profile',I.User]]};

function App(){const[data,edit,reset,sync]=useData(),[me,setMe]=useState(()=>{try{return JSON.parse(sessionStorage.getItem('careflow_ui_user')||'null')}catch{return null}}),[page,setPage]=useState('home'),[note,setNote]=useState('');const tell=x=>{setNote(x);setTimeout(()=>setNote(''),3000)};if(!me)return <Login data={data} edit={edit} done={u=>{sessionStorage.setItem('careflow_ui_user',JSON.stringify(u));setMe(u);setPage('home')}}/>;const title=NAV[me.role].find(x=>x[0]===page)?.[1];return <div className="app-shell"><aside><div className="brand"><I.HeartPulse/><span>CareFlow</span></div><div className="role-card"><div className="avatar">{initials(me.name)}</div><div><b>{me.name}</b><small>{me.role}</small></div></div><nav>{NAV[me.role].map(([k,t,Icon])=><button className={page===k?'active':''} key={k} onClick={()=>setPage(k)}><Icon size={19}/>{t}</button>)}</nav><button className="logout" onClick={()=>{sessionStorage.removeItem('careflow_ui_user');setMe(null)}}><I.LogOut size={19}/>Sign out</button></aside><main><header><div><p className="eyebrow">{sync}</p><h1>{title}</h1></div><button className="reset-button" onClick={()=>{reset();tell('Demo data reset.')}}><I.RotateCcw size={16}/>Reset demo</button></header><View {...{page,data,edit,me,tell,setPage}}/></main>{note&&<div className="toast"><I.CheckCircle2 size={18}/>{note}</div>}</div>}
function DemoLogin({data,edit,done}){const[mode,setMode]=useState('login'),[role,setRole]=useState('patient'),[name,setName]=useState(''),[email,setEmail]=useState('patient@careflow.com'),[pass,setPass]=useState('patient123'),[specialty,setSpecialty]=useState('General Medicine'),[error,setError]=useState('');const pick=r=>{setRole(r);setError('');if(mode==='login'){setEmail(`${r}@careflow.com`);setPass(`${r}123`)}};const submit=()=>{if(mode==='login'){const u=data.users.find(x=>x.email===email&&x.pass===pass&&x.role===role);return u?done(u):setError('Incorrect email, password, or role.')}if(!name||!email||pass.length<8)return setError('Enter your name, email, and a password with at least 8 characters.');if(data.users.some(x=>x.email===email))return setError('An account already exists with this email.');const u={id:uid(),role,name,email,pass};if(role==='doctor')Object.assign(u,{specialty,fee:700,approved:false});edit(d=>d.users.push(u));setError('');done(u)};return <div className="login"><section className="login-copy"><div className="brand"><I.HeartPulse/> CareFlow</div><div><p className="eyebrow">SMART HEALTHCARE PLATFORM</p><h1>{mode==='login'?'Care that moves':'Join CareFlow'}<br/>with your life.</h1><p>{mode==='login'?'Secure care coordination for patients, doctors and administrators.':'Create a patient account or apply for doctor access.'}</p></div><div className="feature"><I.Sparkles/> Specialty recommendation</div><div className="feature"><I.Timer/> Queue prediction</div></section><section className="login-panel"><div className="login-card"><div className="mobile-brand"><I.HeartPulse/> CareFlow</div><h2>{mode==='login'?'Welcome back':'Create account'}</h2><p>{mode==='login'?'Choose a workspace to test.':'Doctor accounts require administrator approval before patient booking.'}</p><div className="roles">{(mode==='login'?['patient','doctor','admin']:['patient','doctor']).map(r=><button key={r} onClick={()=>pick(r)} className={role===r?'selected':''}>{r==='patient'?<I.User/>:r==='doctor'?<I.Stethoscope/>:<I.ShieldCheck/>}{r}</button>)}</div>{mode==='register'&&<label>Full name<input value={name} onChange={e=>setName(e.target.value)} placeholder="Your full name"/></label>}<label>Email<input value={email} onChange={e=>setEmail(e.target.value)}/></label><label>Password<input type="password" value={pass} onChange={e=>setPass(e.target.value)} onKeyDown={e=>e.key==='Enter'&&submit()}/></label>{mode==='register'&&role==='doctor'&&<label>Specialty<select value={specialty} onChange={e=>setSpecialty(e.target.value)}>{data.departments.map(x=><option key={x}>{x}</option>)}</select></label>}{error&&<p className="login-error">{error}</p>}<button className="primary wide" onClick={submit}>{mode==='login'?'Sign in':'Create account'} <I.ArrowRight size={18}/></button><button className="plain-link" onClick={()=>{setMode(mode==='login'?'register':'login');setError('')}}>{mode==='login'?'Create a new patient or doctor account':'Already have an account? Sign in'}</button>{mode==='login'&&<small className="demo">patient123 · doctor123 · admin123</small>}</div></section></div>}
function Login({data,edit,done}){const[mode,setMode]=useState('login'),[role,setRole]=useState('patient'),[name,setName]=useState(''),[email,setEmail]=useState('patient@careflow.com'),[password,setPassword]=useState('patient123'),[specialty,setSpecialty]=useState('General Medicine'),[error,setError]=useState(''),[busy,setBusy]=useState(false);const pick=r=>{setRole(r);setError('');if(mode==='login'){setEmail(`${r}@careflow.com`);setPassword(`${r}123`)}};const submit=async()=>{if(mode==='register'&&(!name.trim()||password.length<8))return setError('Enter your name and a password with at least 8 characters.');setBusy(true);setError('');try{const body=mode==='register'?{fullName:name.trim(),email,password,role,specialty,fee:700}:{email,password};const response=await fetch(`${API}/auth/${mode==='register'?'register':'login'}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const payload=await response.json();if(!response.ok)throw new Error(payload.error||'Unable to sign in');if(payload.user.role!==role)throw new Error('Choose the role assigned to this account.');sessionStorage.setItem('careflow_token',payload.token);let appUser=data.users.find(x=>x.email.toLowerCase()===payload.user.email.toLowerCase());if(!appUser){appUser={id:String(payload.user.id),role:payload.user.role,name:payload.user.fullName,email:payload.user.email,blood:payload.user.bloodGroup,allergies:payload.user.allergies};if(role==='doctor')Object.assign(appUser,{specialty,fee:700,approved:false});edit(d=>d.users.push(appUser));}done(appUser)}catch(e){setError(e.message)}finally{setBusy(false)}};return <div className="login"><section className="login-copy"><div className="brand"><I.HeartPulse/> CareFlow</div><div><p className="eyebrow">SMART HEALTHCARE PLATFORM</p><h1>{mode==='login'?'Care that moves':'Join CareFlow'}<br/>with your life.</h1><p>Secure patient, doctor, and administrator access.</p></div><div className="feature"><I.Sparkles/> Specialty recommendation</div><div className="feature"><I.Timer/> Queue prediction</div></section><section className="login-panel"><div className="login-card"><div className="mobile-brand"><I.HeartPulse/> CareFlow</div><h2>{mode==='login'?'Welcome back':'Create account'}</h2><p>{mode==='login'?'Use your CareFlow account.':'New doctor applications require administrator approval.'}</p><div className="roles">{(mode==='login'?['patient','doctor','admin']:['patient','doctor']).map(r=><button key={r} onClick={()=>pick(r)} className={role===r?'selected':''}>{r==='patient'?<I.User/>:r==='doctor'?<I.Stethoscope/>:<I.ShieldCheck/>}{r}</button>)}</div>{mode==='register'&&<label>Full name<input value={name} onChange={e=>setName(e.target.value)} placeholder="Your full name"/></label>}<label>Email<input type="email" value={email} onChange={e=>setEmail(e.target.value)}/></label><label>Password<input type="password" value={password} onChange={e=>setPassword(e.target.value)} onKeyDown={e=>e.key==='Enter'&&submit()}/></label>{mode==='register'&&role==='doctor'&&<label>Specialty<select value={specialty} onChange={e=>setSpecialty(e.target.value)}>{data.departments.map(x=><option key={x}>{x}</option>)}</select></label>}{error&&<p className="login-error">{error}</p>}<button className="primary wide" disabled={busy} onClick={submit}>{busy?'Please wait…':mode==='login'?'Sign in':'Create account'} <I.ArrowRight size={18}/></button><button className="plain-link" onClick={()=>{setMode(mode==='login'?'register':'login');setError('')}}>{mode==='login'?'Create a new patient or doctor account':'Already have an account? Sign in'}</button>{mode==='login'&&<small className="demo">patient123 · doctor123 · admin123</small>}</div></section></div>}
function ReminderNotifier({data,me,tell}){useEffect(()=>{if(me.role!=='patient'||!('Notification' in window))return;const notify=()=>{const now=new Date(),time=now.toTimeString().slice(0,5),today=now.toDateString();for(const reminder of data.reminders.filter(item=>item.patient===me.id&&item.active)){if(reminderTimeKey(reminder.time)!==time)continue;const key=`careflow-reminder-${reminder.id}-${today}`;if(sessionStorage.getItem(key))continue;sessionStorage.setItem(key,'sent');if(Notification.permission==='granted')new Notification('CareFlow medicine reminder',{body:`Time to take ${reminder.medicine} — ${reminder.dose||'as prescribed'}.`});tell(`Medicine reminder: ${reminder.medicine}`)}};if(Notification.permission==='default')Notification.requestPermission();notify();const timer=window.setInterval(notify,30000);return()=>window.clearInterval(timer)},[data.reminders,me.id,me.role,tell]);return null}
function View(p){return <>{p.me.role==='patient'&&<ReminderNotifier {...p}/>} {p.me.role==='patient'?<Patient {...p}/>:p.me.role==='doctor'?<Doctor {...p}/>:<Admin {...p}/>}</>}
function Patient({page,data,edit,me,tell,setPage}){if(page==='book')return <Booking {...{data,edit,me,tell}}/>;if(page==='appointments')return <Appointments {...{data,edit,me,tell}}/>;if(page==='records')return <Records data={data} patient={me.id}/>;if(page==='symptoms')return <Symptoms {...{edit,me}}/>;if(page==='reminders')return <Reminders {...{data,edit,me,tell}}/>;if(page==='profile')return <Profile me={me}/>;const ap=data.appointments.find(x=>x.patient===me.id&&x.status!=='cancelled');return <><section className="welcome"><div><p className="eyebrow">CARE OVERVIEW</p><h2>Good morning, {me.name.split(' ')[0]}.</h2><p>Your personal healthcare dashboard.</p></div></section><div className="grid two"><div className="next-card"><p>UPCOMING APPOINTMENT</p><h3>{ap?findUser(data,ap.doctor).name:'No appointment scheduled'}</h3>{ap&&<><span><I.CalendarDays size={17}/>{show(findSlot(data,ap.slot).at)}</span><span><I.Timer size={17}/>Predicted wait: <b>{ap.wait} min</b></span></>}</div><div className="care-plan"><div className="section-title"><div><p className="eyebrow">REMINDERS</p><h3>Today’s care plan</h3></div><I.BellRing color="#0f9d92"/></div>{data.reminders.filter(x=>x.patient===me.id&&x.active).map(r=><Rem key={r.id} r={r} edit={edit} tell={tell}/>)}</div></div><section className="section"><p className="eyebrow">QUICK ACTIONS</p><div className="quick-grid"><Quick icon={I.CalendarPlus} title="Book a visit" text="Choose doctor and slot" onClick={()=>setPage('book')}/><Quick icon={I.Sparkles} title="Check symptoms" text="Find the right specialty" onClick={()=>setPage('symptoms')}/><Quick icon={I.AlertTriangle} title="Emergency request" text="Priority queue entry" red onClick={()=>priority(data,edit,me,tell)}/></div></section></>}
function priority(data,edit,me,tell){const doc=data.users.find(x=>x.role==='doctor'&&x.approved),s=data.slots.find(x=>x.doctor===doc.id&&!x.booked);if(!s)return tell('No available slots.');edit(d=>{d.slots.find(x=>x.id===s.id).booked=true;d.appointments.unshift({id:id(),patient:me.id,doctor:doc.id,slot:s.id,status:'confirmed',priority:true,wait:5,created:iso()})});tell('Emergency priority request created.')}
function Booking({data,edit,me,tell}){const docs=data.users.filter(x=>x.role==='doctor'&&x.approved),[doctor,setDoctor]=useState(docs[0]?.id),[chosen,setChosen]=useState(''),[priorityFlag,setPriority]=useState(false),slots=data.slots.filter(x=>x.doctor===doctor&&!x.booked&&!x.unavailable&&!(data.doctorLeaves||[]).some(l=>l.doctor===doctor&&l.date===dateKey(x.at)));const book=()=>{if(!chosen)return tell('Choose a free time slot.');const wait=priorityFlag?5:data.appointments.filter(x=>x.doctor===doctor&&x.status!=='completed'&&!x.priority).length*18;edit(d=>{d.slots.find(x=>x.id===chosen).booked=true;d.appointments.unshift({id:id(),patient:me.id,doctor,slot:chosen,status:'confirmed',priority:priorityFlag,wait,created:iso()})});setChosen('');tell(`Appointment confirmed. Predicted wait: ${wait} minutes.`)};return <div className="form-page"><p className="intro">Availability, priority and wait time update immediately. Doctors on leave cannot be booked.</p><h3>1. Choose a specialist</h3><div className="doctor-list">{docs.map(d=><button key={d.id} className={'doctor-option '+(doctor===d.id?'chosen':'')} onClick={()=>{setDoctor(d.id);setChosen('')}}><div className="doctor-avatar">{initials(d.name)}</div><div><b>{d.name}</b><span>{d.specialty} · Consultation ₹{d.fee}</span></div><I.CheckCircle2 className="pick"/></button>)}</div><h3>2. Choose a time</h3><div className="slots">{slots.map(s=><button key={s.id} className={chosen===s.id?'slot-selected':''} onClick={()=>setChosen(s.id)}>{show(s.at)}<small>{chosen===s.id?'Selected':'Available'}</small></button>)}{!slots.length&&<p className="empty">No bookable slots right now. Please choose another doctor or date.</p>}</div><label className="emergency"><input type="checkbox" checked={priorityFlag} onChange={e=>setPriority(e.target.checked)}/><span><b>Priority / emergency request</b><small>Places this case first in the doctor’s live queue.</small></span></label><button className="primary" onClick={book}>Confirm appointment <I.CheckCircle2 size={18}/></button></div>}
function Appointments({data,edit,me,tell}){return <div className="form-page"><p className="intro">Your booking history and current queue status.</p>{data.appointments.filter(x=>x.patient===me.id).map(a=><div className="record" key={a.id}><div className="record-icon"><I.CalendarDays/></div><div><b>{findUser(data,a.doctor).name}{a.priority?' · Priority':''}</b><small>{show(findSlot(data,a.slot).at)} · {a.status}</small><span>Predicted wait: {a.wait} minutes</span></div>{a.status==='confirmed'&&<button className="text-button" onClick={()=>{edit(d=>{d.appointments.find(x=>x.id===a.id).status='cancelled';d.slots.find(x=>x.id===a.slot).booked=false});tell('Appointment cancelled.')}}>Cancel</button>}</div>)}</div>}
function Symptoms({edit,me}){const[text,setText]=useState(''),[result,setResult]=useState(null),[report,setReport]=useState(''),[analysis,setAnalysis]=useState(null);const headers={'Content-Type':'application/json',Authorization:`Bearer ${sessionStorage.getItem('careflow_token')||''}`};const go=async()=>{try{const r=await fetch(`${API}/symptoms/recommend`,{method:'POST',headers,body:JSON.stringify({symptoms:text})}),data=await r.json();if(!r.ok)throw new Error(data.error);setResult(data);edit(d=>d.symptoms.push({id:id(),patient:me.id,text,specialty:data.recommendedSpecialty,created:iso()}))}catch(e){setResult({message:e.message,recommendedSpecialty:'Unavailable'})}};const analyze=async()=>{try{const r=await fetch(`${API}/reports/analyze`,{method:'POST',headers,body:JSON.stringify({reportText:report})}),data=await r.json();if(!r.ok)throw new Error(data.error);setAnalysis(data)}catch(e){setAnalysis({summary:e.message})}};return <div className="form-page symptom"><p className="intro">Specialty recommendation only — never a diagnosis.</p><textarea value={text} onChange={e=>setText(e.target.value)} placeholder="Example: I have an itchy red rash on my arm..."/><button className="primary" disabled={!text.trim()} onClick={go}><I.Sparkles size={18}/>Find the right specialty</button>{result&&<div className="result"><p>RECOMMENDED SPECIALTY</p><h2>{result.recommendedSpecialty}</h2><span>{result.message}</span><hr/><b>Important:</b> {result.disclaimer||'Seek emergency care for severe or life-threatening symptoms.'}</div>}<h3>AI report explainer</h3><textarea value={report} onChange={e=>setReport(e.target.value)} placeholder="Paste lab-report text for an informational summary..."/><button className="primary" disabled={report.length<10} onClick={analyze}>Analyze report text</button>{analysis&&<div className="result"><p>REPORT SUMMARY</p><span>{analysis.summary}</span>{analysis.questionsForClinician?.length>0&&<ul>{analysis.questionsForClinician.map(q=><li key={q}>{q}</li>)}</ul>}<small>{analysis.safetyNote}</small></div>}</div>}
function DemoRecords({data,patient}){return <div className="records">{data.records.filter(x=>x.patient===patient).map(r=><Card key={r.id} icon={I.FileText} title={r.title} sub={`${r.type} · ${show(r.created)}`} text={r.detail}/>)}{data.prescriptions.filter(x=>x.patient===patient).map(r=><Card key={r.id} icon={I.Pill} title="Prescription" sub={show(r.created)} text={`${r.medicine} · ${r.dose} · ${r.notes}`}/>)}</div>}
function Records(props){const role=JSON.parse(sessionStorage.getItem('careflow_user')||'{}').role;return <><DemoRecords {...props}/>{role==='patient'&&<ReportUpload/>}</>}
function ReportUpload(){const[file,setFile]=useState(null),[note,setNote]=useState('');const upload=async()=>{if(!file)return setNote('Choose a PDF, PNG, or JPG report first.');const form=new FormData();form.append('report',file);form.append('title',file.name);try{const r=await fetch(`${API}/records/upload`,{method:'POST',headers:{Authorization:`Bearer ${sessionStorage.getItem('careflow_token')||''}`},body:form});if(!r.ok)throw new Error();setNote('Lab report uploaded to MongoDB record storage.')}catch{setNote('Upload failed. Restart the API server and try again.')}};return <div className="inline-form"><input type="file" accept="application/pdf,image/png,image/jpeg" onChange={e=>setFile(e.target.files?.[0])}/><button className="primary" onClick={upload}>Upload lab report</button>{note&&<small>{note}</small>}</div>}
function Card({icon:Icon,title,sub,text,action}){return <div className="record"><div className="record-icon"><Icon/></div><div><b>{title}</b><small>{sub}</small><span>{text}</span></div>{action}</div>}
function Rem({r,edit,tell}){return <div className="reminder"><div className="icon-disc"><I.Pill size={18}/></div><div><b>{r.medicine}</b><span>{r.dose} · {r.time}</span></div><button onClick={()=>{edit(d=>d.reminders.find(x=>x.id===r.id).active=false);tell('Marked as taken.')}}>Mark taken</button></div>}
function Reminders({data,edit,me,tell}){const[m,setM]=useState(''),[time,setT]=useState('');return <div className="form-page"><div className="schedule-card">{data.reminders.filter(x=>x.patient===me.id&&x.active).map(r=><Rem key={r.id} r={r} edit={edit} tell={tell}/>)}</div><div className="inline-form"><input placeholder="Medicine" value={m} onChange={e=>setM(e.target.value)}/><input placeholder="Time" value={time} onChange={e=>setT(e.target.value)}/><button className="primary" onClick={()=>{if(m&&time){edit(d=>d.reminders.push({id:id(),patient:me.id,medicine:m,dose:'As prescribed',time,active:true}));setM('');setT('');tell('Reminder added.')}}}>Add reminder</button></div></div>}
function Doctor({page,data,edit,me,tell}){if(page==='queue')return <Queue {...{data,edit,me,tell}}/>;if(page==='emergencies')return <Queue {...{data,edit,me,tell,priorityOnly:true}}/>;if(page==='schedule')return <Schedule {...{data,edit,me,tell}}/>;if(page==='patients')return <DoctorPatients {...{data,edit,me,tell}}/>;if(page==='profile')return <Profile me={me}/>;const count=data.appointments.filter(x=>x.doctor===me.id&&['confirmed','in_progress'].includes(x.status)).length;return <><section className="welcome"><div><p className="eyebrow">CLINIC OPERATIONS</p><h2>Welcome, {me.name}.</h2><p>Today’s workflow is ready for you.</p></div></section><div className="stat-grid"><Stat icon={I.Users} value={count} label="Current queue"/><Stat icon={I.AlertTriangle} value={data.appointments.filter(x=>x.doctor===me.id&&x.priority).length} label="Priority cases"/><Stat icon={I.Timer} value="18 min" label="Average consultation"/></div><Queue {...{data,edit,me,tell,compact:true}}/></>}
function Queue({data,edit,me,tell,priorityOnly=false}){let rows=data.appointments.filter(x=>x.doctor===me.id&&['confirmed','in_progress'].includes(x.status));if(priorityOnly)rows=rows.filter(x=>x.priority);rows.sort((a,b)=>Number(b.priority)-Number(a.priority)||a.created.localeCompare(b.created));const setStatus=(appointment,status)=>edit(d=>{const row=d.appointments.find(x=>x.id===appointment.id);row.status=status;if(status==='cancelled'){const slot=d.slots.find(x=>x.id===appointment.slot);if(slot)slot.booked=false}});return <section className="section"><div className="section-title"><div><p className="eyebrow">{priorityOnly?'EMERGENCY CASES':'LIVE QUEUE'}</p><h3>{priorityOnly?'Priority appointments':'Today’s patients'}</h3></div></div><div className="table"><div className="table-head"><span>Patient</span><span>Time</span><span>Wait</span><span>Status</span></div>{rows.map(a=><div className="table-row" key={a.id}><span className="patient-cell"><div className={'mini-avatar '+(a.priority?'urgent':'')}>{a.priority?<I.AlertTriangle size={15}/>:initials(findUser(data,a.patient).name)}</div><b>{findUser(data,a.patient).name}{a.priority?' · Priority':''}</b></span><span>{show(findSlot(data,a.slot).at)}</span><span>{a.wait} min</span><select value={a.status} onChange={e=>{setStatus(a,e.target.value);tell(`Appointment marked ${e.target.value}. The patient can see this update.`)}}><option value="confirmed">Confirmed</option><option value="in_progress">In progress</option><option value="completed">Completed</option><option value="cancelled">Cancelled</option></select></div>)}{!rows.length&&<div className="empty">No matching appointments.</div>}</div></section>}
function Schedule({data,edit,me,tell}){const[at,setAt]=useState(''),[repeat,setRepeat]=useState(1),[leaveDate,setLeaveDate]=useState(''),[leaveReason,setLeaveReason]=useState('');const slots=data.slots.filter(x=>x.doctor===me.id).sort((a,b)=>new Date(a.at)-new Date(b.at)),leaves=(data.doctorLeaves||[]).filter(x=>x.doctor===me.id);const addSlots=()=>{if(!at)return tell('Choose a date and time.');const first=new Date(at);edit(d=>{for(let week=0;week<Math.max(1,Number(repeat)||1);week++){const next=new Date(first);next.setDate(first.getDate()+week*7);if(!d.slots.some(s=>s.doctor===me.id&&new Date(s.at).getTime()===next.getTime()))d.slots.push({id:id(),doctor:me.id,at:next.toISOString(),booked:false,unavailable:false})}});setAt('');tell(repeat>1?`${repeat} weekly slots added to your calendar.`:'Availability slot added.')};const addLeave=()=>{if(!leaveDate)return tell('Choose a leave date.');edit(d=>{d.doctorLeaves=d.doctorLeaves||[];if(d.doctorLeaves.some(x=>x.doctor===me.id&&x.date===leaveDate))return;d.doctorLeaves.push({id:id(),doctor:me.id,date:leaveDate,reason:leaveReason});d.slots.filter(s=>s.doctor===me.id&&dateKey(s.at)===leaveDate&&!s.booked).forEach(s=>s.unavailable=true)});setLeaveDate('');setLeaveReason('');tell('Leave recorded. Unbooked slots for that day are closed.')};return <div className="form-page"><p className="intro">Manage any future date. Add one slot or repeat the same clinic time weekly across a month; booked visits are never silently removed.</p><div className="schedule-card">{slots.map(s=><div className="toggle-row" key={s.id}><div><b>{show(s.at)}</b><small>{s.booked?'Booked':s.unavailable?'Closed / leave':'Available for booking'}</small></div>{!s.booked&&<button className={'toggle '+(!s.unavailable?'on':'')} onClick={()=>{edit(d=>{const row=d.slots.find(x=>x.id===s.id);row.unavailable=!row.unavailable});tell(s.unavailable?'Slot reopened.':'Slot closed.')}}><i/></button>}</div>)}{!slots.length&&<div className="empty">No future slots yet.</div>}</div><h3>Add availability</h3><div className="inline-form"><input type="datetime-local" value={at} onChange={e=>setAt(e.target.value)}/><input type="number" min="1" max="12" value={repeat} onChange={e=>setRepeat(e.target.value)} title="Repeat weekly for number of weeks"/><button className="primary" onClick={addSlots}>{repeat>1?'Add weekly slots':'Add slot'}</button></div><small className="intro">Repeat value: 4 means the selected day/time is added for four consecutive weeks.</small><h3>Leave management</h3><div className="inline-form"><input type="date" value={leaveDate} onChange={e=>setLeaveDate(e.target.value)}/><input value={leaveReason} onChange={e=>setLeaveReason(e.target.value)} placeholder="Reason (optional)"/><button className="primary" onClick={addLeave}>Mark leave</button></div>{leaves.map(l=><div className="toggle-row" key={l.id}><div><b>Leave — {l.date}</b><small>{l.reason||'Unavailable for new bookings'}</small></div><button className="text-button" onClick={()=>{edit(d=>{d.doctorLeaves=(d.doctorLeaves||[]).filter(x=>x.id!==l.id);d.slots.filter(s=>s.doctor===me.id&&dateKey(s.at)===l.date&&!s.booked).forEach(s=>s.unavailable=false)});tell('Leave removed; unbooked slots reopened.')}}>Remove leave</button></div>)}</div>}
function Patients({data,edit,me,tell}){const allIds=[...new Set(data.appointments.filter(x=>x.doctor===me.id&&x.status!=='cancelled').map(x=>x.patient))],archived=new Set((data.archivedPatients||[]).filter(x=>x.doctor===me.id).map(x=>x.patient)),ids=allIds.filter(x=>!archived.has(x)),[patient,setPatient]=useState(ids[0]||allIds[0]),[search,setSearch]=useState(''),[note,setNote]=useState(''),[medicine,setMedicine]=useState(''),[reminderTime,setReminderTime]=useState('09:00');const matches=data.users.filter(x=>x.role==='patient'&&search.trim()&&`${x.name} ${x.email}`.toLowerCase().includes(search.toLowerCase())).slice(0,6);if(!patient)return <div className="form-page"><p className="intro">Search for a patient who has returned, or wait for an appointment assignment.</p><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Find previous patient by name or email"/>{matches.map(x=><button className="doctor-option" key={x.id} onClick={()=>setPatient(x.id)}><div className="doctor-avatar">{initials(x.name)}</div><div><b>{x.name}</b><span>{x.email}</span></div></button>)}</div>;const p=findUser(data,patient),isArchived=archived.has(patient);const prescribe=()=>{if(!medicine||!reminderTime)return tell('Enter a medicine and reminder time.');const prescriptionId=id();edit(d=>{d.prescriptions.unshift({id:prescriptionId,patient,doctor:me.id,medicine,dose:'As prescribed',time:reminderTime,notes:'Follow doctor instructions.',created:iso()});d.reminders.push({id:id(),prescription:prescriptionId,patient,medicine,dose:'As prescribed',time:reminderTime,active:true})});fetch(`${API}/notifications/reminder-email`,{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${sessionStorage.getItem('careflow_token')||''}`},body:JSON.stringify({patientEmail:p.email,medicine,time:reminderTime})}).then(r=>tell(r.ok?`Prescription created. Email reminder sent for ${reminderTime}.`:`Prescription created. Browser reminder set for ${reminderTime}; email needs Brevo setup.`)).catch(()=>tell(`Prescription created. Browser reminder set for ${reminderTime}.`));setMedicine('')};const archivePatient=()=>{edit(d=>{d.archivedPatients=d.archivedPatients||[];if(isArchived)d.archivedPatients=d.archivedPatients.filter(x=>!(x.doctor===me.id&&x.patient===patient));else d.archivedPatients.push({doctor:me.id,patient})});tell(isArchived?'Patient restored to active list.':'Patient archived from your active list; clinical history is retained.')};return <div className="form-page"><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Find a returning patient by name or email"/>{search&&<div className="doctor-list">{matches.map(x=><button className={'doctor-option '+(patient===x.id?'chosen':'')} key={x.id} onClick={()=>{setPatient(x.id);setSearch('')}}><div className="doctor-avatar">{initials(x.name)}</div><div><b>{x.name}</b><span>{x.email}</span></div></button>)}</div>}<div className="doctor-list">{ids.map(pid=>{const x=findUser(data,pid);return <button key={pid} className={'doctor-option '+(patient===pid?'chosen':'')} onClick={()=>setPatient(pid)}><div className="doctor-avatar">{initials(x.name)}</div><div><b>{x.name}</b><span>{x.blood||'Blood group not recorded'} · Allergies: {x.allergies||'None recorded'}</span></div></button>})}</div><div className="section-title"><div><h3>{p.name} — shared clinical history</h3><p className="intro">Previous consultation notes, reports, and prescriptions follow the patient when they book with a new doctor.</p></div><button className="text-button" onClick={archivePatient}>{isArchived?'Restore patient':'Archive from active list'}</button></div><Records data={data} patient={patient}/><textarea value={note} onChange={e=>setNote(e.target.value)} placeholder="Add consultation note..."/><button className="primary" onClick={()=>{if(note){edit(d=>d.records.unshift({id:id(),patient,doctor:me.id,title:'Consultation note',type:'Encounter',detail:note,created:iso()}));setNote('');tell('Consultation note saved.')}}}>Save note</button><h3>Prescription and reminder</h3><div className="inline-form"><input value={medicine} onChange={e=>setMedicine(e.target.value)} placeholder="Medicine name"/><input type="time" value={reminderTime} onChange={e=>setReminderTime(e.target.value)} title="Reminder time"/><button className="primary" onClick={prescribe}>Prescribe</button></div><div className="records">{data.prescriptions.filter(x=>x.patient===patient).map(rx=><div className="record" key={rx.id}><div className="record-icon"><I.Pill/></div><div><b>{rx.medicine}</b><small>{rx.dose} · {rx.time}</small><span>{rx.notes}</span></div>{rx.doctor===me.id&&<button className="text-button" onClick={()=>{edit(d=>{d.prescriptions=d.prescriptions.filter(x=>x.id!==rx.id);d.reminders=d.reminders.filter(x=>x.prescription!==rx.id)});tell('Prescription removed and its reminder cancelled.')}}>Remove</button>}</div>)}</div></div>}
function Admin({page,data,edit,me,tell}){if(page==='approvals')return <Approvals {...{data,edit,tell}}/>;if(page==='departments')return <Departments {...{data,edit,tell}}/>;if(page==='analytics')return <Analytics data={data}/>;if(page==='disputes')return <Disputes {...{data,edit,tell}}/>;if(page==='profile')return <Profile me={me}/>;return <><section className="welcome"><div><p className="eyebrow">CARE OPERATIONS</p><h2>System overview</h2><p>Manage the healthcare platform from one place.</p></div></section><div className="stat-grid"><Stat icon={I.Users} value={data.users.filter(x=>x.role==='patient').length} label="Patients"/><Stat icon={I.Stethoscope} value={data.users.filter(x=>x.role==='doctor'&&x.approved).length} label="Active doctors"/><Stat icon={I.CalendarCheck} value={data.appointments.length} label="Appointments"/><Stat icon={I.UserRoundCheck} value={data.users.filter(x=>x.role==='doctor'&&!x.approved).length} label="Pending approvals"/></div></>}
function DemoApprovals({data,edit,tell}){const rows=data.users.filter(x=>x.role==='doctor'&&!x.approved);return <div className="form-page"><p className="intro">Approve doctors to make them immediately available in patient booking.</p>{rows.map(d=><div className="approval" key={d.id}><div className="doctor-avatar">{initials(d.name)}</div><div><b>{d.name} · {d.specialty}</b><span>Fee ₹{d.fee} · Credential review pending</span></div><button className="text-button" onClick={()=>{edit(x=>x.users=x.users.filter(v=>v.id!==d.id));tell('Registration rejected.')}}>Reject</button><button className="primary small" onClick={()=>{edit(x=>x.users.find(v=>v.id===d.id).approved=true);tell('Doctor approved. Now visible in booking.')}}>Approve</button></div>)}{!rows.length&&<div className="empty"><I.CheckCircle2/>All registrations reviewed.</div>}</div>}
function Approvals({data,edit,tell}){const[rows,setRows]=useState([]),[error,setError]=useState('');const headers=()=>({'Authorization':`Bearer ${sessionStorage.getItem('careflow_token')||''}`});const load=async()=>{try{const response=await fetch(`${API}/admin/pending-doctors`,{headers:headers()});const body=await response.json();if(!response.ok)throw new Error(body.error||'Unable to load approvals');setRows(body)}catch(e){setError(e.message)}};useEffect(()=>{load()},[]);const approve=async row=>{try{const r=await fetch(`${API}/admin/doctors/${row.user._id}`,{method:'PATCH',headers:{...headers(),'Content-Type':'application/json'},body:JSON.stringify({approved:true})});if(!r.ok)throw new Error();setRows(items=>items.filter(item=>item._id!==row._id));edit(d=>{const local=d.users.find(u=>u.email?.toLowerCase()===row.user.email?.toLowerCase());if(local)local.approved=true});tell('Doctor approved in MongoDB and now available for booking.')}catch{setError('Unable to approve doctor.')}};const reject=async row=>{try{const r=await fetch(`${API}/admin/doctors/${row.user._id}`,{method:'DELETE',headers:headers()});if(!r.ok)throw new Error();setRows(items=>items.filter(item=>item._id!==row._id));edit(d=>d.users=d.users.filter(u=>u.email?.toLowerCase()!==row.user.email?.toLowerCase()));tell('Doctor registration rejected and removed.')}catch{setError('Unable to reject doctor.')}};return <div className="form-page"><p className="intro">Review doctor registrations from the secure MongoDB database.</p>{error&&<p className="login-error">{error}</p>}{rows.map(row=><div className="approval" key={row._id}><div className="doctor-avatar">{initials(row.user.fullName)}</div><div><b>{row.user.fullName} · {row.specialty}</b><span>Fee ₹{row.fee} · Credential review pending</span></div><button className="text-button" onClick={()=>reject(row)}>Reject</button><button className="primary small" onClick={()=>approve(row)}>Approve</button></div>)}{!error&&!rows.length&&<div className="empty"><I.CheckCircle2/>All registrations reviewed.</div>}</div>}
function Departments({data,edit,tell}){const[name,setName]=useState('');return <div className="form-page"><div className="schedule-card">{data.departments.map(x=><div className="toggle-row" key={x}><b>{x}</b><button className="text-button" onClick={()=>{edit(d=>d.departments=d.departments.filter(v=>v!==x));tell('Department removed.')}}>Remove</button></div>)}</div><div className="inline-form"><input value={name} onChange={e=>setName(e.target.value)} placeholder="New department"/><button className="primary" onClick={()=>{if(name&&!data.departments.includes(name)){edit(d=>d.departments.push(name));setName('');tell('Department added.')}}}>Add department</button></div></div>}
function Analytics({data}){const download=()=>{const text='Patient,Doctor,Time,Status,Priority,Wait minutes\n'+data.appointments.map(a=>[findUser(data,a.patient).name,findUser(data,a.doctor).name,show(findSlot(data,a.slot).at),a.status,a.priority,a.wait].join(',')).join('\n');const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([text],{type:'text/csv'}));link.download='careflow-report.csv';link.click()};const days=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];const byDay=days.map(day=>data.appointments.filter(a=>new Date(a.created).toLocaleDateString('en-US',{weekday:'short'})===day).length);const states=['confirmed','in_progress','completed','cancelled'];const byStatus=states.map(status=>data.appointments.filter(a=>a.status===status).length);const barData={labels:days,datasets:[{label:'Appointments created',data:byDay,backgroundColor:'#0f9d92',borderRadius:7,maxBarThickness:42}]};const doughnutData={labels:['Confirmed','In progress','Completed','Cancelled'],datasets:[{data:byStatus,backgroundColor:['#0f9d92','#1d72b8','#6b7c93','#d95d67'],borderWidth:0}]};const options={responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{displayColors:false}},scales:{x:{grid:{display:false},border:{display:false}},y:{beginAtZero:true,ticks:{precision:0},grid:{color:'#e8eef3'},border:{display:false}}}};return <><div className="section-title"><div><p className="eyebrow">SYSTEM REPORTING</p><h3>Analytics and report generator</h3></div><button className="primary" onClick={download}><I.Download size={17}/>Download CSV report</button></div><div className="stat-grid"><Stat icon={I.Users} value={data.users.filter(x=>x.role==='patient').length} label="Patients"/><Stat icon={I.Stethoscope} value={data.users.filter(x=>x.role==='doctor'&&x.approved).length} label="Doctors"/><Stat icon={I.CalendarCheck} value={data.appointments.length} label="Appointments"/><Stat icon={I.AlertTriangle} value={data.appointments.filter(x=>x.priority).length} label="Priority cases"/></div><div className="analytics-grid"><section className="chart-card"><p className="eyebrow">APPOINTMENTS CREATED</p><h3>Volume by weekday</h3><div className="chart-canvas"><Bar data={barData} options={options}/></div></section><section className="chart-card"><p className="eyebrow">APPOINTMENT STATUS</p><h3>Current queue mix</h3><div className="chart-canvas"><Doughnut data={doughnutData} options={{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom',labels:{boxWidth:10,padding:14}}},cutout:'68%' }}/></div></section></div></>}
function Disputes({data,edit,tell}){const[rows,setRows]=useState([]),[error,setError]=useState('');const headers={'Content-Type':'application/json',Authorization:`Bearer ${sessionStorage.getItem('careflow_token')||''}`};const load=async()=>{try{const r=await fetch(`${API}/admin/disputes`,{headers}),body=await r.json();if(!r.ok)throw new Error(body.error);setRows(body)}catch(e){setError(e.message)}};useEffect(()=>{load()},[]);const resolve=async row=>{try{const r=await fetch(`${API}/admin/disputes/${row._id}`,{method:'PATCH',headers,body:JSON.stringify({status:'resolved',resolutionNote:'Resolved by administrator'})});if(!r.ok)throw new Error();setRows(items=>items.map(x=>x._id===row._id?{...x,status:'resolved'}:x));tell('Dispute resolved in MongoDB.')}catch{setError('Unable to resolve dispute.')}};return <div className="form-page">{error&&<p className="login-error">{error}</p>}{rows.map(x=><div className="action-card" key={x._id}><I.MessageSquareWarning/><div><b>{x.title}</b><span>{x.patient?.fullName||'Patient'} · Status: {x.status}</span></div><button className="primary small" onClick={()=>resolve(x)}>Resolve</button></div>)}{!error&&!rows.length&&<div className="empty">No open disputes.</div>}</div>}
function Profile({me}){const[profile,setProfile]=useState({fullName:me.name||'',age:'',bloodGroup:me.blood||'',allergies:me.allergies||'',chronicConditions:''}),[note,setNote]=useState('');useEffect(()=>{fetch(`${API}/me`,{headers:{Authorization:`Bearer ${sessionStorage.getItem('careflow_token')||''}`}}).then(r=>r.ok?r.json():null).then(x=>x&&setProfile({fullName:x.fullName||'',age:x.age||'',bloodGroup:x.bloodGroup||'',allergies:x.allergies||'',chronicConditions:x.chronicConditions||''})).catch(()=>{})},[]);const save=async()=>{try{const r=await fetch(`${API}/me`,{method:'PATCH',headers:{'Content-Type':'application/json',Authorization:`Bearer ${sessionStorage.getItem('careflow_token')||''}`},body:JSON.stringify(profile)});if(!r.ok)throw new Error();setNote('Profile saved to MongoDB.')}catch{setNote('Unable to save profile. Restart the API server and sign in again.')}};if(me.role!=='patient')return <DemoProfile me={me}/>;return <div className="profile"><div className="profile-avatar">{initials(profile.fullName||me.name)}</div><h2>{profile.fullName||me.name}</h2><p>Patient profile</p><div className="form-page"><label>Full name<input value={profile.fullName} onChange={e=>setProfile({...profile,fullName:e.target.value})}/></label><label>Age<input type="number" value={profile.age} onChange={e=>setProfile({...profile,age:e.target.value})}/></label><label>Blood group<input value={profile.bloodGroup} onChange={e=>setProfile({...profile,bloodGroup:e.target.value})}/></label><label>Allergies<input value={profile.allergies} onChange={e=>setProfile({...profile,allergies:e.target.value})}/></label><label>Chronic conditions<input value={profile.chronicConditions} onChange={e=>setProfile({...profile,chronicConditions:e.target.value})}/></label><button className="primary" onClick={save}>Save profile</button>{note&&<p className="intro">{note}</p>}</div></div>}
function DemoProfile({me}){const rows=me.role==='doctor'?[['Specialty',me.specialty],['Consultation fee',`₹${me.fee}`]]:[['Access level','System administrator'],['Storage','MongoDB Atlas']];return <div className="profile"><div className="profile-avatar">{initials(me.name)}</div><h2>{me.name}</h2><p>{me.role} account</p><div className="profile-card">{rows.map(x=><div key={x[0]}><span>{x[0]}</span><b>{x[1]}</b></div>)}</div></div>}
function Stat({icon:Icon,value,label}){return <div className="stat"><div><Icon size={20}/></div><b>{value}</b><span>{label}</span></div>}
function Quick({icon:Icon,title,text,red,onClick}){return <button className="quick" onClick={onClick}><div className={red?'red':''}><Icon size={22}/></div><b>{title}</b><span>{text}</span></button>}
function DoctorPatients({data,edit,me,tell}){const ids=[...new Set(data.appointments.filter(x=>x.doctor===me.id&&x.status!=='cancelled').map(x=>x.patient))],[patient,setPatient]=useState(ids[0]),[medicine,setMedicine]=useState(''),[time,setTime]=useState('09:00');if(!patient)return <div className="empty">No assigned patients yet.</div>;const p=findUser(data,patient),rows=data.prescriptions.filter(x=>x.patient===patient),stop=rx=>{if(!window.confirm(`Stop ${rx.medicine}? Its reminder will also stop, but the prescription remains in history.`))return;edit(d=>{const item=d.prescriptions.find(x=>x.id===rx.id);item.status='discontinued';item.stoppedAt=iso();item.stoppedBy=me.id;d.reminders.filter(x=>x.prescription===rx.id||(x.patient===patient&&x.medicine===rx.medicine&&x.time===rx.time)).forEach(x=>x.active=false)});tell(`${rx.medicine} is discontinued. The record remains in patient history.`)};const prescribe=()=>{if(!medicine.trim())return tell('Enter a medicine name.');const rx=id();edit(d=>{d.prescriptions.unshift({id:rx,patient,doctor:me.id,medicine:medicine.trim(),dose:'As prescribed',time,status:'active',notes:'Follow doctor instructions.',created:iso()});d.reminders.push({id:id(),prescription:rx,patient,medicine:medicine.trim(),dose:'As prescribed',time,active:true})});setMedicine('');tell('Medicine prescribed and reminder scheduled.')};return <div className="form-page"><p className="intro">Stopping a medicine never deletes the clinical record. It is retained as discontinued for future doctors.</p><div className="doctor-list">{ids.map(pid=>{const x=findUser(data,pid);return <button key={pid} className={'doctor-option '+(patient===pid?'chosen':'')} onClick={()=>setPatient(pid)}><div className="doctor-avatar">{initials(x.name)}</div><div><b>{x.name}</b><span>{x.blood||'Blood group not recorded'} · Allergies: {x.allergies||'None recorded'}</span></div></button>})}</div><h3>{p.name} — medicines</h3><div className="medicine-manager">{rows.map(rx=><div className="medicine-card" key={rx.id}><div><b><I.Pill size={17}/> {rx.medicine}</b><small>{rx.dose||'As prescribed'} · {rx.time||'No reminder time'}</small><span>{rx.status==='discontinued'?`Discontinued ${show(rx.stoppedAt)}`:'Active prescription'}</span></div>{(rx.doctor===me.id||(!rx.doctor&&me.id==='d1'))&&rx.status!=='discontinued'?<button className="stop-medicine" onClick={()=>stop(rx)}><I.Ban size={16}/>Stop medicine</button>:<small>{rx.status==='discontinued'?'History retained':'Prescribed by another doctor'}</small>}</div>)}{!rows.length&&<div className="empty">No medicines recorded.</div>}</div><h3>New prescription</h3><div className="inline-form"><input value={medicine} onChange={e=>setMedicine(e.target.value)} placeholder="Medicine name"/><input type="time" value={time} onChange={e=>setTime(e.target.value)}/><button className="primary" onClick={prescribe}>Prescribe</button></div><h3>Clinical history</h3><Records data={data} patient={patient}/></div>}
